import React, { useState } from 'react';

type FilterLabel = 'All' | 'Active' | 'Archived' | 'Starred';

const FILTERS: FilterLabel[] = ['All', 'Active', 'Archived', 'Starred'];

const chipStyles = `
  @layer components {
    .chip-bar {
      display: flex;
      gap: var(--shelf-chip-gap);
      padding: var(--shelf-chip-bar-paddingBlock) var(--shelf-chip-bar-paddingInline);
      background-color: var(--shelf-chip-bar-bgColor-default);
    }

    .chip-button {
      appearance: none;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      padding: var(--shelf-chip-paddingBlock) var(--shelf-chip-paddingInline);
      background-color: var(--shelf-chip-bgColor-default);
      color: var(--shelf-chip-fgColor-default);
      border: var(--shelf-chip-borderWidth) solid var(--shelf-chip-borderColor-default);
      border-radius: var(--shelf-chip-borderRadius);
      cursor: pointer;
      font-size: var(--shelf-chip-fontSize);
    }

    .chip-button[aria-pressed="true"] {
      background-color: var(--shelf-chip-bgColor-pressed);
      color: var(--shelf-chip-fgColor-pressed);
      border-color: var(--shelf-chip-borderColor-pressed);
    }

    .chip-button:hover:not([aria-pressed="true"]) {
      background-color: var(--shelf-chip-bgColor-hover);
    }
  }
`;

export function ChipFilter(): React.ReactElement {
  const [selected, setSelected] = useState<FilterLabel>('All');

  return (
    <>
      <style>{chipStyles}</style>
      <div className="chip-bar" role="group" aria-label="Filter chips">
        {FILTERS.map((label) => (
          <button
            key={label}
            type="button"
            className="chip-button"
            aria-pressed={selected === label}
            onClick={() => setSelected(label)}
          >
            {label}
          </button>
        ))}
      </div>
    </>
  );
}
